<?php
/** INT-006 native atomic receipts, canonical matching and replay. Builder: Shashi. */
if (!defined('ABSPATH') || strpos(DB_NAME,'idlm_test_')!==0) { exit(1); }
function idlm_wa_native_fixture($phone='919999900001') {
    // These inbox contracts exercise immediate existing-contact receipt, independent of connector tests.
    update_option('idlm_interakt_lead_capture','0');
    wp_cache_delete('idlm_meta_webhook_app_secret','options');wp_cache_delete('alloptions','options');
    update_option('idlm_meta_webhook_enabled','1');update_option('idlm_meta_webhook_app_secret','synthetic-inbox-secret');update_option('idlm_interakt_enabled','1');update_option('idlm_interakt_webhook_secret','synthetic-inbox-secret');
    return idlm_lifecycle_fixture(array('phone'=>$phone));
}
function idlm_wa_native_message($id,$phone='919999900001') {return array('id'=>$id,'from'=>$phone,'type'=>'text','text'=>array('body'=>'Synthetic '.$id));}
function idlm_wa_native_body($messages) {return array('object'=>'whatsapp_business_account','entry'=>array(array('changes'=>array(array('value'=>array('messages'=>$messages))))));}
function idlm_wa_native_call($body,$provider='meta',$secret='synthetic-inbox-secret') {
    $r=new WP_REST_Request('POST','/idlm/v1/'.$provider.'-webhook');$raw=wp_json_encode($body);$r->set_body($raw);$r->set_header($provider==='meta'?'X-Hub-Signature-256':'Interakt-Signature','sha256='.hash_hmac('sha256',$raw,$secret));return $provider==='meta'?IDLM_Interakt::handle_meta_webhook_request($r):IDLM_Interakt::handle_webhook_request($r);
}
function idlm_wa_native_count($lead) {global $wpdb;return (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_lead_activity_log WHERE lead_id=%d AND activity_type='whatsapp_reply'",$lead));}
function idlm_wa_native_receipt($id,$provider='meta') {return 'idlm_whatsapp_receipt_'.hash('sha256',$provider.'|'.$id);}
idlm_integration_test('T07-T09-N-INT006-complete mixed entry change text button list media and status batch replays once',static function():void {
    $lead=idlm_wa_native_fixture();$messages=array(idlm_wa_native_message('native-text'),array('id'=>'native-button','from'=>'919999900001','type'=>'button','button'=>array('text'=>'Synthetic button')),array('id'=>'native-list','from'=>'919999900001','type'=>'interactive','interactive'=>array('list_reply'=>array('title'=>'Synthetic list'))),array('id'=>'native-media','from'=>'919999900001','type'=>'image','image'=>array('id'=>'synthetic-media')));
    $body=idlm_wa_native_body(array_slice($messages,0,2));$body['entry'][0]['changes'][]=array('value'=>array('statuses'=>array(array('status'=>'delivered'))));$body['entry'][]=array('changes'=>array(array('value'=>array('messages'=>array_slice($messages,2)))));
    $r=idlm_wa_native_call($body);idlm_integration_assert_same(200,$r->get_status());idlm_integration_assert_same(4,$r->get_data()['processed']);idlm_integration_assert_same(4,idlm_wa_native_count($lead));$r=idlm_wa_native_call($body);idlm_integration_assert_same(4,$r->get_data()['replayed']);idlm_integration_assert_same(4,idlm_wa_native_count($lead));
});
idlm_integration_test('T07-N-INT006-malformed oversized missing ID and bad signature batches write nothing',static function():void {
    $lead=idlm_wa_native_fixture('919999900002');$good=idlm_wa_native_message('reject-good','919999900002');$bad=$good;unset($bad['id']);
    foreach(array(array(idlm_wa_native_body(array($good,$bad)),400),array(idlm_wa_native_body(array_fill(0,101,$good)),413),array(array('object'=>'whatsapp_business_account','entry'=>array(array('changes'=>'bad'))),400)) as [$body,$status]){idlm_integration_assert_same($status,idlm_wa_native_call($body)->get_status());}
    idlm_integration_assert_same(401,idlm_wa_native_call(idlm_wa_native_body(array($good)),'meta','wrong')->get_status());idlm_integration_assert_same(0,idlm_wa_native_count($lead));
});
idlm_integration_test('T09-N-INT006-partial batch is explicit and replays resume uncommitted messages',static function():void {
    $lead=idlm_wa_native_fixture('919999900003');$body=idlm_wa_native_body(array(idlm_wa_native_message('partial-first','919999900003'),idlm_wa_native_message('partial-later','449999900003')));$r=idlm_wa_native_call($body);idlm_integration_assert_same(409,$r->get_status());idlm_integration_assert_same(1,$r->get_data()['processed']);$later=idlm_wa_native_fixture('449999900003');$r=idlm_wa_native_call($body);idlm_integration_assert_same(200,$r->get_status());idlm_integration_assert_same(1,$r->get_data()['replayed']);idlm_integration_assert_same(1,$r->get_data()['processed']);idlm_integration_assert_same(1,idlm_wa_native_count($lead));idlm_integration_assert_same(1,idlm_wa_native_count($later));
});
idlm_integration_test('T09-N-INT006-full-phone canonical matching refuses suffix and conflicting canonical identities',static function():void {
    global $wpdb;$lead=idlm_wa_native_fixture('+91 (99999) 00004');$foreign=idlm_wa_native_fixture('449999900004');$duplicate=idlm_wa_native_fixture('09999900004');$wpdb->update($wpdb->prefix.'idlm_leads',array('is_duplicate'=>1,'duplicate_of_id'=>$lead),array('id'=>$duplicate));$r=idlm_wa_native_call(idlm_wa_native_body(array(idlm_wa_native_message('canonical','919999900004'))));idlm_integration_assert_same(200,$r->get_status());idlm_integration_assert_same(1,idlm_wa_native_count($lead));idlm_integration_assert_same(0,idlm_wa_native_count($foreign));idlm_integration_assert_same(0,idlm_wa_native_count($duplicate));
    $other=idlm_wa_native_fixture('9999900004');$r=idlm_wa_native_call(idlm_wa_native_body(array(idlm_wa_native_message('ambiguous','919999900004'))));idlm_integration_assert_same(409,$r->get_status());idlm_integration_assert_same(0,idlm_wa_native_count($other));
});
idlm_integration_test('T09-N-INT006-required activity receipt commit and options engine faults never acknowledge',static function():void {
    global $wpdb;$lead=idlm_wa_native_fixture('919999900005');
    foreach(array('activity','receipt','commit') as $fault){$id='fault-'.$fault;$body=idlm_wa_native_body(array(idlm_wa_native_message($id,'919999900005')));$before=idlm_wa_native_count($lead);$filter=static function($sql)use($fault,$wpdb){$match=$fault==='activity'?strpos($sql,'INSERT INTO `'.$wpdb->prefix.'idlm_lead_activity_log`')===0:($fault==='receipt'?strpos($sql,'INSERT INTO `'.$wpdb->options.'`')===0 && strpos($sql,'idlm_whatsapp_receipt_')!==false:$sql==='COMMIT');return $match?'SELECT * FROM idlm_int006_missing_table':$sql;};add_filter('query',$filter);try{$r=idlm_wa_native_call($body);}finally{remove_filter('query',$filter);}idlm_integration_assert_same(503,$r->get_status(),$fault);idlm_integration_assert_same($before,idlm_wa_native_count($lead));idlm_integration_assert_same(false,get_option(idlm_wa_native_receipt($id)));idlm_integration_assert_same(200,idlm_wa_native_call($body)->get_status());}
    $wpdb->query("ALTER TABLE {$wpdb->options} ENGINE=MyISAM");try{idlm_integration_assert_same(503,idlm_wa_native_call(idlm_wa_native_body(array(idlm_wa_native_message('bad-engine','919999900005'))))->get_status());}finally{$wpdb->query("ALTER TABLE {$wpdb->options} ENGINE=InnoDB");}
});
idlm_integration_test('T07-N-INT006-Interakt ID media namespace changed replay and current secret checks',static function():void {
    global $wpdb,$config;$lead=idlm_wa_native_fixture('919999900006');$body=array('type'=>'message_received','data'=>array('customer'=>array('channel_phone_number'=>'919999900006'),'message'=>array('id'=>'same-id','message_content_type'=>'Image','media_url'=>'https://example.test/private','message'=>'')));
    idlm_integration_assert_same(200,idlm_wa_native_call($body,'interakt')->get_status());idlm_integration_assert_same(1,idlm_wa_native_call($body,'interakt')->get_data()['replayed']);$body['data']['message']['message']='Changed';idlm_integration_assert_same(409,idlm_wa_native_call($body,'interakt')->get_status());idlm_integration_assert_same(200,idlm_wa_native_call(idlm_wa_native_body(array(idlm_wa_native_message('same-id','919999900006'))))->get_status());
    get_option('idlm_meta_webhook_app_secret');$other=new wpdb($config['db_user'],$config['db_password'],$config['db_name'],$config['db_host']);$other->update($wpdb->options,array('option_value'=>'rotated-synthetic-secret'),array('option_name'=>'idlm_meta_webhook_app_secret'));$other->close();$b=idlm_wa_native_body(array(idlm_wa_native_message('rotated','919999900006')));idlm_integration_assert_same(401,idlm_wa_native_call($b)->get_status());idlm_integration_assert_same(200,idlm_wa_native_call($b,'meta','rotated-synthetic-secret')->get_status());
});
idlm_integration_test('T09-C-INT006-independent replay and interruption before or after commit append at most once',static function():void {
    $lead=idlm_wa_native_fixture('919999900007');
    foreach(array('wa-beforecommit','wa-aftercommit') as $mode){$id='crash-'.$mode;$r=idlm_integration_worker(array($mode,$id,'919999900007'));idlm_integration_assert_same(77,$r['status'],$r['stderr']);$b=idlm_wa_native_body(array(idlm_wa_native_message($id,'919999900007')));idlm_integration_assert_same(200,idlm_wa_native_call($b)->get_status());idlm_integration_assert_same(200,idlm_wa_native_call($b)->get_status());}idlm_integration_assert_same(2,idlm_wa_native_count($lead));
    @unlink(WP_CONTENT_DIR.'/wa-barrier');$jobs=array();foreach(array(1,2) as $i){$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/worker.php').' wa-race wa-concurrent 919999900007';$proc=proc_open($cmd,array(1=>array('pipe','w'),2=>array('pipe','w')),$pipes);$jobs[]=array($proc,$pipes);}foreach($jobs as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);idlm_integration_assert_same(0,proc_close($proc),$out.$err);}idlm_integration_assert_same(3,idlm_wa_native_count($lead));
});
idlm_integration_test('T09-T16-T17-N-INT006-minimal receipt survives activity pruning restore deletion and reset',static function():void {
    global $wpdb;idlm_native_backup_fixture();$lead=idlm_wa_native_fixture('919999900008');$b=idlm_wa_native_body(array(idlm_wa_native_message('retain','919999900008')));idlm_integration_assert_same(200,idlm_wa_native_call($b)->get_status());$key=idlm_wa_native_receipt('retain');$receipt=get_option($key);idlm_integration_assert_true(is_array($receipt));idlm_integration_assert_true(strpos(serialize($receipt),'919999900008')===false);$snapshot=idlm_native_backup_call('snapshot');idlm_integration_assert_true(!is_wp_error($snapshot));foreach($snapshot['options'] as $option){idlm_integration_assert_true($option['option_name']!==$key);}
    $wpdb->delete($wpdb->prefix.'idlm_lead_activity_log',array('lead_id'=>$lead));idlm_integration_assert_same(1,idlm_wa_native_call($b)->get_data()['replayed']);idlm_integration_assert_same(true,idlm_native_backup_call('restore_payload',$snapshot));idlm_integration_assert_same(1,idlm_wa_native_call($b)->get_data()['replayed']);$count=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_leads");idlm_integration_assert_true(!is_wp_error(IDLM_Lead_Deletion_Service::reset_all((string)$count)));idlm_integration_assert_same(1,idlm_wa_native_call($b)->get_data()['replayed']);idlm_integration_assert_same(0,idlm_wa_native_count($lead));
});
idlm_integration_test('T09-N-INT006-active caller transaction and malformed receipt refuse writes',static function():void {
    global $wpdb;$lead=idlm_wa_native_fixture('919999900009');$b=idlm_wa_native_body(array(idlm_wa_native_message('active','919999900009')));$wpdb->query('START TRANSACTION');try{idlm_integration_assert_same(503,idlm_wa_native_call($b)->get_status());}finally{$wpdb->query('ROLLBACK');}idlm_integration_assert_same(0,idlm_wa_native_count($lead));add_option(idlm_wa_native_receipt('active'),array('version'=>999),'','no');idlm_integration_assert_same(409,idlm_wa_native_call($b)->get_status());
});
